// ОКРУЖЕНИЕ: у new02 на 19.11 нет чата «בדיקה כללי» — вместо него «QA П1 0010». Вход в подарок — через меню «פעולות על הצ'אט».
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/new02.json'), colorScheme: 'dark' });

const PARTNER = 'QA П1 0010';

test.describe('Раунд 13: подарки (#47a8b8 #dc2c6f #676952 #e0de78)', () => {
  test('Назад с экрана отправки → выбор подарков, ✕ → чат @iphone @prod-safe', async ({ page }) => {
    const sendGiftRequests: string[] = [];
    page.on('request', (r) => {
      if (/send_gift|payment|purchase/i.test(r.url())) sendGiftRequests.push(r.url());
    });

    const sendScreenBack = page.getByRole('button', { name: 'חזרה' }).last();
    const pickerFilter = page.getByRole('button', { name: 'עד ₪5' });
    const chatField = page.getByRole('textbox', { name: 'כתוב הודעה' });

    // Предусловие: чат → меню → «שליחת מתנה ל־…» (лист выбора подарков).
    await page.goto('/matches');
    await page.getByRole('button', { name: new RegExp(`^${PARTNER}`) }).click();
    await page.waitForURL(/\/chat\//);
    await page.getByRole('button', { name: 'פעולות על הצ\'אט' }).click();
    await page.getByRole('button', { name: new RegExp(`שליחת מתנה ל־.*${PARTNER}`) }).click();

    // 1. Чат → 🎁 → «ורד זהב» → экран отправки; стрелка «назад».
    await page.getByRole('button', { name: /^ורד זהב · ₪/ }).click();
    await expect(page.getByRole('button', { name: 'שליחת מתנה • ₪4.90' })).toBeVisible();
    await sendScreenBack.click();
    await expect(pickerFilter).toBeVisible();
    await expect(page.getByRole('button', { name: 'הכול', exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: /^דובי פרחים · ₪/ })).toBeVisible();
    await expect(chatField).toBeHidden();

    // 2. В магазине выбрать «דובי פרחים» → экран отправки; стрелка «назад».
    await page.getByRole('button', { name: /^דובי פרחים · ₪/ }).click();
    await expect(page.getByRole('button', { name: 'שליחת מתנה • ₪7.90' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'שליחת מתנה • ₪4.90' })).toHaveCount(0);
    await sendScreenBack.click();
    await expect(pickerFilter).toBeVisible();
    await expect(chatField).toBeHidden();

    // 3. ✕ магазина.
    await page.getByRole('button', { name: 'סגירה' }).click();
    await expect(chatField).toBeVisible();
    expect(sendGiftRequests, 'send_gift/оплата не вызывались').toEqual([]);
  });
});
